/**
 * Nightly batch that flags open, past-due invoices as Overdue and
 * writes a single run summary in finish().
 *
 * Database.Stateful is required so the running totals survive across
 * transactions (one transaction per chunk) regardless of batch size.
 * without sharing is intentional: this is a system-wide finance job
 * that must process every overdue invoice.
 */
public without sharing class OverdueInvoiceBatch implements Database.Batchable<SObject>, Database.Stateful {

    private Integer recordsUpdated = 0;
    private Integer recordsFailed = 0;
    private Decimal overdueAmountTotal = 0;

    public OverdueInvoiceBatch() {
        this.recordsUpdated = 0;
        this.recordsFailed = 0;
        this.overdueAmountTotal = 0;
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        return Database.getQueryLocator([
            SELECT Id, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = 'Open'
            AND Due_Date__c < TODAY
        ]);
    }

    public void execute(Database.BatchableContext context, List<SObject> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        List<FB_Invoice__c> invoices = new List<FB_Invoice__c>();
        for (SObject record : scope) {
            FB_Invoice__c invoice = (FB_Invoice__c) record;
            invoice.Status__c = 'Overdue';
            invoices.add(invoice);
        }

        // allOrNone = false: one failing invoice (e.g. validation rule on
        // blank Customer_Email__c) must not roll back the rest of the chunk.
        List<Database.SaveResult> results = Database.update(invoices, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                recordsUpdated++;
                Decimal amount = invoices[i].Amount__c;
                if (amount != null) {
                    overdueAmountTotal += amount;
                }
            } else {
                recordsFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext context) {
        insert new FB_Job_Summary__c(
            Job_Name__c = 'OverdueInvoiceBatch',
            Records_Updated__c = recordsUpdated,
            Records_Failed__c = recordsFailed,
            Overdue_Amount__c = overdueAmountTotal
        );
    }
}
