public without sharing class ContactTriggerHandler {
    public static void beforeInsert(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, true);
    }

    public static void beforeUpdate(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, false);
    }

    public static void afterInsert(List<Contact> newContacts) {
        if (newContacts == null || newContacts.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        for (Contact contact : newContacts) {
            if (contact.AccountId != null && String.isNotBlank(contact.Phone)) {
                accountIds.add(contact.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        Map<Id, Account> accountsToUpdateById = new Map<Id, Account>();
        for (Contact contact : newContacts) {
            if (contact.AccountId == null || String.isBlank(contact.Phone)) {
                continue;
            }
            // The first eligible contact for an account wins; once an
            // account is queued for update, later contacts must not
            // overwrite the phone set by that first contact.
            if (accountsToUpdateById.containsKey(contact.AccountId)) {
                continue;
            }

            Account account = accountsById.get(contact.AccountId);
            if (account == null || String.isNotBlank(account.Phone)) {
                continue;
            }

            account.Phone = contact.Phone;
            accountsToUpdateById.put(account.Id, account);
        }

        if (!accountsToUpdateById.isEmpty()) {
            update accountsToUpdateById.values();
        }
    }

    private static void applyAccountDefaults(
        List<Contact> contacts,
        Boolean isInsert
    ) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        for (Contact contact : contacts) {
            if (contact.AccountId == null) {
                continue;
            }

            Boolean needsMailingCountry = String.isBlank(contact.MailingCountry);
            Boolean needsLeadSource =
                isInsert && String.isBlank(contact.LeadSource);

            if (needsMailingCountry || needsLeadSource) {
                accountIds.add(contact.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [
                SELECT Id, BillingCountry, AccountSource
                FROM Account
                WHERE Id IN :accountIds
            ]
        );

        for (Contact contact : contacts) {
            if (contact.AccountId == null) {
                continue;
            }

            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }

            if (String.isBlank(contact.MailingCountry)) {
                contact.MailingCountry = account.BillingCountry;
            }
            if (isInsert && String.isBlank(contact.LeadSource)) {
                contact.LeadSource = account.AccountSource;
            }
        }
    }
}
