public class ExchangeRateClient {
    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(
        String baseCurrency,
        Set<String> quoteCurrencies
    ) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException(
                'At least one quote currency is required.'
            );
        }

        String normalizedBase = normalizeCurrencyCode(baseCurrency, 'Base');

        Set<String> normalizedQuoteSet = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            normalizedQuoteSet.add(
                normalizeCurrencyCode(quoteCurrency, 'Quote')
            );
        }

        List<String> normalizedQuotes = new List<String>(normalizedQuoteSet);
        normalizedQuotes.sort();

        List<String> encodedQuotes = new List<String>();
        for (String quoteCurrency : normalizedQuotes) {
            encodedQuotes.add(EncodingUtil.urlEncode(quoteCurrency, 'UTF-8'));
        }

        String endpoint =
            'callout:FB_Exchange_Rates/v1/latest?base=' +
            EncodingUtil.urlEncode(normalizedBase, 'UTF-8') +
            '&symbols=' +
            String.join(encodedQuotes, ',');

        Http http = new Http();
        HttpResponse response;

        for (Integer attempt = 0; attempt < 2; attempt++) {
            response = http.send(buildRequest(endpoint));
            if (response.getStatusCode() != 503 || attempt == 1) {
                break;
            }
        }

        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' +
                response.getStatusCode() +
                '.'
            );
        }

        String body = response.getBody();
        if (String.isBlank(body)) {
            throw new ExchangeRateException(
                'Exchange rate response body could not be parsed.'
            );
        }

        Object parsedBody;
        try {
            parsedBody = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException(
                'Exchange rate response body could not be parsed: ' +
                e.getMessage()
            );
        }

        if (!(parsedBody instanceof Map<String, Object>)) {
            throw new ExchangeRateException(
                'Exchange rate response body could not be parsed.'
            );
        }

        Map<String, Object> payload = (Map<String, Object>) parsedBody;
        Object ratesObject = payload.get('rates');

        if (!(ratesObject instanceof Map<String, Object>)) {
            throw new ExchangeRateException(
                'Exchange rate response does not contain a valid rates object.'
            );
        }

        Map<String, Object> rates = (Map<String, Object>) ratesObject;
        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String quoteCurrency : normalizedQuotes) {
            if (!rates.containsKey(quoteCurrency)) {
                throw new ExchangeRateException(
                    'Exchange rate response is missing a rate for currency ' +
                    quoteCurrency +
                    '.'
                );
            }

            Object rateValue = rates.get(quoteCurrency);
            Decimal rate;

            if (rateValue instanceof Decimal) {
                rate = (Decimal) rateValue;
            } else if (rateValue instanceof Integer) {
                rate = Decimal.valueOf((Integer) rateValue);
            } else if (rateValue instanceof Long) {
                rate = Decimal.valueOf((Long) rateValue);
            } else if (rateValue instanceof Double) {
                rate = Decimal.valueOf((Double) rateValue);
            } else {
                throw new ExchangeRateException(
                    'Exchange rate response contains an invalid rate for currency ' +
                    quoteCurrency +
                    '.'
                );
            }

            result.put(quoteCurrency, rate);
        }

        return result;
    }

    private static HttpRequest buildRequest(String endpoint) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        return request;
    }

    private static String normalizeCurrencyCode(
        String currencyCode,
        String currencyType
    ) {
        if (currencyCode == null) {
            throw new ExchangeRateException(
                currencyType +
                ' currency code must be exactly three letters A-Z.'
            );
        }

        String normalized = currencyCode.trim().toUpperCase();

        if (!normalized.matches('[A-Z]{3}')) {
            throw new ExchangeRateException(
                currencyType +
                ' currency code must be exactly three letters A-Z: ' +
                currencyCode
            );
        }

        return normalized;
    }
}
