public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field must be specified.');
            }

            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.SObjectType objectType = findObjectType(objectApiName.trim());
            if (objectType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();

            if (!objectDescribe.isAccessible()) {
                throw new SearchException(
                    'The running user cannot read object ' + objectDescribe.getName() + '.'
                );
            }

            if (!objectDescribe.isQueryable()) {
                throw new SearchException(
                    'Object is not queryable: ' + objectDescribe.getName()
                );
            }

            Map<String, Schema.DescribeFieldResult> fieldsByLowerCaseName =
                new Map<String, Schema.DescribeFieldResult>();

            for (Schema.SObjectField fieldToken : objectDescribe.fields.getMap().values()) {
                Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
                fieldsByLowerCaseName.put(fieldDescribe.getName().toLowerCase(), fieldDescribe);
            }

            Set<String> selectedLowerCaseNames = new Set<String>{ 'id' };
            List<String> selectFields = new List<String>();

            for (String requestedField : fields) {
                Schema.DescribeFieldResult fieldDescribe = requireAccessibleField(
                    fieldsByLowerCaseName,
                    requestedField,
                    'requested'
                );
                String lowerCaseName = fieldDescribe.getName().toLowerCase();
                if (!selectedLowerCaseNames.contains(lowerCaseName)) {
                    selectedLowerCaseNames.add(lowerCaseName);
                    selectFields.add(fieldDescribe.getName());
                }
            }

            Map<String, Object> bindVariables = new Map<String, Object>();
            List<String> whereClauses = new List<String>();

            if (filters != null && !filters.isEmpty()) {
                Integer bindIndex = 0;
                for (String filterField : filters.keySet()) {
                    Schema.DescribeFieldResult fieldDescribe = requireAccessibleField(
                        fieldsByLowerCaseName,
                        filterField,
                        'filter'
                    );

                    if (!fieldDescribe.isFilterable()) {
                        throw new SearchException(
                            'Field cannot be filtered: ' + fieldDescribe.getName()
                        );
                    }

                    Object filterValue = filters.get(filterField);
                    if (filterValue == null) {
                        whereClauses.add(fieldDescribe.getName() + ' = NULL');
                    } else {
                        String bindName = 'filter' + bindIndex;
                        whereClauses.add(fieldDescribe.getName() + ' = :' + bindName);
                        bindVariables.put(bindName, filterValue);
                    }
                    bindIndex++;
                }
            }

            String canonicalOrderByField;
            if (!String.isBlank(orderByField)) {
                Schema.DescribeFieldResult fieldDescribe = requireAccessibleField(
                    fieldsByLowerCaseName,
                    orderByField,
                    'order-by'
                );

                if (!fieldDescribe.isSortable()) {
                    throw new SearchException(
                        'Field cannot be sorted: ' + fieldDescribe.getName()
                    );
                }

                canonicalOrderByField = fieldDescribe.getName();
            }

            String soql = 'SELECT Id';
            if (!selectFields.isEmpty()) {
                soql += ', ' + String.join(selectFields, ', ');
            }
            soql += ' FROM ' + objectDescribe.getName();

            if (!whereClauses.isEmpty()) {
                soql += ' WHERE ' + String.join(whereClauses, ' AND ');
            }

            if (canonicalOrderByField != null) {
                soql += ' ORDER BY ' + canonicalOrderByField + ' ASC';
            }

            soql += ' LIMIT ' + maxRows;

            return (List<SObject>) Database.queryWithBinds(
                soql,
                bindVariables,
                AccessLevel.USER_MODE
            );
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            String message = e.getMessage();
            throw new SearchException(
                String.isBlank(message) ? 'The search could not be completed.' : message
            );
        }
    }

    private static Schema.SObjectType findObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        for (String candidateName : globalDescribe.keySet()) {
            if (candidateName != null && candidateName.equalsIgnoreCase(objectApiName)) {
                return globalDescribe.get(candidateName);
            }
        }
        return null;
    }

    private static Schema.DescribeFieldResult requireAccessibleField(
        Map<String, Schema.DescribeFieldResult> fieldsByLowerCaseName,
        String fieldApiName,
        String role
    ) {
        if (String.isBlank(fieldApiName)) {
            throw new SearchException('Invalid ' + role + ' field: ' + fieldApiName);
        }

        Schema.DescribeFieldResult fieldDescribe =
            fieldsByLowerCaseName.get(fieldApiName.trim().toLowerCase());

        if (fieldDescribe == null) {
            throw new SearchException('Field does not exist on the object: ' + fieldApiName);
        }

        if (!fieldDescribe.isAccessible()) {
            throw new SearchException(
                'The running user cannot read field ' + fieldDescribe.getName() + '.'
            );
        }

        return fieldDescribe;
    }
}
