public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(required=true label='Email' description='Email address to find a Contact by.')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the matching Contact, or null if not found.')
        public Id contactId;

        @InvocableVariable(label='Found' description='True if a matching Contact was found.')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds the earliest created Contact matching each email address, case-insensitively.' category='Contact')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedKeys = new List<String>();
        Set<String> emailsToQuery = new Set<String>();

        for (Request request : requests) {
            String trimmedEmail = (request == null || request.email == null)
                ? null
                : request.email.trim();

            if (String.isBlank(trimmedEmail)) {
                normalizedKeys.add(null);
            } else {
                normalizedKeys.add(trimmedEmail.toLowerCase());
                emailsToQuery.add(trimmedEmail);
            }
        }

        Map<String, Id> earliestContactByEmail = new Map<String, Id>();
        if (!emailsToQuery.isEmpty()) {
            // Single bulk query. SOQL string matching is case-insensitive;
            // results are also keyed by lower-cased email below to guarantee
            // case-insensitive mapping back to each request.
            // Ordered by CreatedDate so the first contact seen per email is
            // the earliest created one.
            for (Contact contact : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToQuery
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (String.isBlank(contact.Email)) {
                    continue;
                }
                String key = contact.Email.trim().toLowerCase();
                if (!earliestContactByEmail.containsKey(key)) {
                    earliestContactByEmail.put(key, contact.Id);
                }
            }
        }

        for (String key : normalizedKeys) {
            Result result = new Result();
            Id contactId = (key == null) ? null : earliestContactByEmail.get(key);
            result.contactId = contactId;
            result.found = contactId != null;
            results.add(result);
        }

        return results;
    }
}
