public class OrderPayloadParser {

    public class PayloadException extends Exception {
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;

        public Order() {
            this.lines = new List<Line>();
            this.total = 0;
        }
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;

        public Line() {
            this.discount = 0;
        }
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Order payload body is null or blank.');
        }

        try {
            JSONParser parser = JSON.createParser(body);

            if (parser.nextToken() != JSONToken.START_OBJECT) {
                throw new PayloadException('Order payload must be a JSON object.');
            }

            Order result = new Order();

            while (true) {
                JSONToken token = parser.nextToken();
                if (token == null) {
                    throw new PayloadException('Unexpected end of order payload.');
                }
                if (token == JSONToken.END_OBJECT) {
                    break;
                }
                if (token != JSONToken.FIELD_NAME) {
                    throw new PayloadException('Invalid order payload structure.');
                }

                String fieldName = parser.getCurrentName();
                JSONToken valueToken = parser.nextToken();
                if (valueToken == null) {
                    throw new PayloadException('Unexpected end of order payload.');
                }

                if (fieldName == 'number') {
                    if (valueToken == JSONToken.VALUE_NULL) {
                        result.orderNumber = null;
                    } else if (valueToken == JSONToken.VALUE_STRING) {
                        result.orderNumber = parser.getText();
                    } else {
                        throw new PayloadException('Order number must be a string.');
                    }
                } else if (fieldName == 'date') {
                    if (valueToken == JSONToken.VALUE_NULL) {
                        result.orderDate = null;
                    } else if (valueToken == JSONToken.VALUE_STRING) {
                        result.orderDate = parseDateValue(parser.getText());
                    } else {
                        throw new PayloadException('Order date must be a string in yyyy-MM-dd format.');
                    }
                } else if (fieldName == 'currency') {
                    if (valueToken == JSONToken.VALUE_NULL) {
                        result.currencyCode = null;
                    } else if (valueToken == JSONToken.VALUE_STRING) {
                        result.currencyCode = parser.getText();
                    } else {
                        throw new PayloadException('Currency must be a string.');
                    }
                } else if (fieldName == 'customer') {
                    if (valueToken == JSONToken.VALUE_NULL) {
                        result.customerEmail = null;
                    } else if (valueToken == JSONToken.START_OBJECT) {
                        result.customerEmail = parseCustomer(parser);
                    } else {
                        throw new PayloadException('Customer must be an object.');
                    }
                } else if (fieldName == 'lines') {
                    if (valueToken == JSONToken.VALUE_NULL) {
                        result.lines = new List<Line>();
                    } else if (valueToken == JSONToken.START_ARRAY) {
                        result.lines = parseLines(parser);
                    } else {
                        throw new PayloadException('Lines must be an array.');
                    }
                } else {
                    skipValue(parser);
                }
            }

            if (parser.nextToken() != null) {
                throw new PayloadException('Unexpected content after order payload.');
            }

            if (String.isBlank(result.orderNumber)) {
                throw new PayloadException('Order number is required.');
            }

            if (result.lines == null) {
                result.lines = new List<Line>();
            }

            Decimal total = 0;
            for (Line line : result.lines) {
                if (line.discount == null) {
                    line.discount = 0;
                }
                line.lineTotal = (line.quantity * line.unitPrice * (1 - line.discount))
                    .setScale(2, RoundingMode.HALF_UP);
                total += line.lineTotal;
            }
            result.total = total;
            return result;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            String message = e.getMessage();
            throw new PayloadException(
                String.isBlank(message)
                    ? 'Invalid order payload.'
                    : 'Invalid order payload: ' + message
            );
        }
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is null.');
        }

        try {
            Integer lineCount = 0;
            if (order.lines != null) {
                lineCount = order.lines.size();
            }

            Decimal total = order.total;
            if (total == null) {
                total = 0;
            }

            JSONGenerator generator = JSON.createGenerator(false);
            generator.writeStartObject();
            if (order.orderNumber == null) {
                generator.writeNullField('number');
            } else {
                generator.writeStringField('number', order.orderNumber);
            }
            generator.writeStringField('status', 'RECEIVED');
            generator.writeNumberField('lineCount', lineCount);
            generator.writeNumberField('total', total);
            generator.writeEndObject();

            String acknowledgement = generator.getAsString();
            generator.close();
            return acknowledgement;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            String message = e.getMessage();
            throw new PayloadException(
                String.isBlank(message)
                    ? 'Could not create acknowledgement.'
                    : 'Could not create acknowledgement: ' + message
            );
        }
    }

    private static String parseCustomer(JSONParser parser) {
        String email = null;

        while (true) {
            JSONToken token = parser.nextToken();
            if (token == null) {
                throw new PayloadException('Unexpected end of order payload.');
            }
            if (token == JSONToken.END_OBJECT) {
                break;
            }
            if (token != JSONToken.FIELD_NAME) {
                throw new PayloadException('Invalid customer structure.');
            }

            String fieldName = parser.getCurrentName();
            JSONToken valueToken = parser.nextToken();
            if (valueToken == null) {
                throw new PayloadException('Unexpected end of order payload.');
            }

            if (fieldName == 'email') {
                if (valueToken == JSONToken.VALUE_NULL) {
                    email = null;
                } else if (valueToken == JSONToken.VALUE_STRING) {
                    email = parser.getText();
                } else {
                    throw new PayloadException('Customer email must be a string.');
                }
            } else {
                skipValue(parser);
            }
        }

        return email;
    }

    private static List<Line> parseLines(JSONParser parser) {
        List<Line> lines = new List<Line>();

        while (true) {
            JSONToken token = parser.nextToken();
            if (token == null) {
                throw new PayloadException('Unexpected end of order payload.');
            }
            if (token == JSONToken.END_ARRAY) {
                break;
            }
            if (token != JSONToken.START_OBJECT) {
                throw new PayloadException('Each order line must be an object.');
            }
            lines.add(parseLine(parser));
        }

        return lines;
    }

    private static Line parseLine(JSONParser parser) {
        Line line = new Line();
        line.discount = 0;

        while (true) {
            JSONToken token = parser.nextToken();
            if (token == null) {
                throw new PayloadException('Unexpected end of order payload.');
            }
            if (token == JSONToken.END_OBJECT) {
                break;
            }
            if (token != JSONToken.FIELD_NAME) {
                throw new PayloadException('Invalid order line structure.');
            }

            String fieldName = parser.getCurrentName();
            JSONToken valueToken = parser.nextToken();
            if (valueToken == null) {
                throw new PayloadException('Unexpected end of order payload.');
            }

            if (fieldName == 'sku') {
                if (valueToken == JSONToken.VALUE_NULL) {
                    line.sku = null;
                } else if (valueToken == JSONToken.VALUE_STRING) {
                    line.sku = parser.getText();
                } else {
                    throw new PayloadException('Line sku must be a string.');
                }
            } else if (fieldName == 'quantity') {
                if (valueToken == JSONToken.VALUE_NULL) {
                    line.quantity = null;
                } else if (
                    valueToken == JSONToken.VALUE_NUMBER_INT ||
                    valueToken == JSONToken.VALUE_NUMBER_FLOAT
                ) {
                    Decimal quantityDecimal = parser.getDecimalValue();
                    if (quantityDecimal == null) {
                        throw new PayloadException('Line quantity must be a number.');
                    }
                    Decimal wholeQuantity = quantityDecimal.setScale(0, RoundingMode.DOWN);
                    if (quantityDecimal != wholeQuantity) {
                        throw new PayloadException('Line quantity must be a whole number.');
                    }
                    if (wholeQuantity.abs() > 2147483647) {
                        throw new PayloadException('Line quantity is out of range.');
                    }
                    line.quantity = wholeQuantity.intValue();
                } else {
                    throw new PayloadException('Line quantity must be a number.');
                }
            } else if (fieldName == 'unitPrice') {
                if (valueToken == JSONToken.VALUE_NULL) {
                    line.unitPrice = null;
                } else if (
                    valueToken == JSONToken.VALUE_NUMBER_INT ||
                    valueToken == JSONToken.VALUE_NUMBER_FLOAT
                ) {
                    line.unitPrice = parser.getDecimalValue();
                    if (line.unitPrice == null) {
                        throw new PayloadException('Line unitPrice must be a number.');
                    }
                } else {
                    throw new PayloadException('Line unitPrice must be a number.');
                }
            } else if (fieldName == 'discount') {
                if (valueToken == JSONToken.VALUE_NULL) {
                    line.discount = 0;
                } else if (
                    valueToken == JSONToken.VALUE_NUMBER_INT ||
                    valueToken == JSONToken.VALUE_NUMBER_FLOAT
                ) {
                    line.discount = parser.getDecimalValue();
                    if (line.discount == null) {
                        throw new PayloadException('Line discount must be a number.');
                    }
                } else {
                    throw new PayloadException('Line discount must be a number.');
                }
            } else {
                skipValue(parser);
            }
        }

        if (String.isBlank(line.sku)) {
            throw new PayloadException('Line sku is required.');
        }
        if (line.quantity == null || line.quantity <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }
        if (line.unitPrice == null || line.unitPrice < 0) {
            throw new PayloadException('Line unitPrice must not be negative.');
        }
        if (line.discount == null) {
            line.discount = 0;
        }
        if (line.discount < 0 || line.discount > 1) {
            throw new PayloadException('Line discount must be between 0 and 1.');
        }

        return line;
    }

    private static Date parseDateValue(String value) {
        if (
            String.isBlank(value) ||
            value.length() != 10 ||
            value.substring(4, 5) != '-' ||
            value.substring(7, 8) != '-'
        ) {
            throw new PayloadException('Order date must use yyyy-MM-dd format.');
        }

        String yearText = value.substring(0, 4);
        String monthText = value.substring(5, 7);
        String dayText = value.substring(8, 10);

        if (
            !yearText.isNumeric() ||
            !monthText.isNumeric() ||
            !dayText.isNumeric()
        ) {
            throw new PayloadException('Order date must use yyyy-MM-dd format.');
        }

        Integer year = Integer.valueOf(yearText);
        Integer month = Integer.valueOf(monthText);
        Integer day = Integer.valueOf(dayText);

        if (month < 1 || month > 12) {
            throw new PayloadException('Order date is invalid.');
        }

        Boolean isLeapYear =
            (Math.mod(year, 400) == 0) ||
            (Math.mod(year, 4) == 0 && Math.mod(year, 100) != 0);
        Integer februaryDays = isLeapYear ? 29 : 28;
        List<Integer> daysInMonth = new List<Integer>{
            31, februaryDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31
        };

        if (day < 1 || day > daysInMonth[month - 1]) {
            throw new PayloadException('Order date is invalid.');
        }

        return Date.newInstance(year, month, day);
    }

    private static void skipValue(JSONParser parser) {
        JSONToken token = parser.getCurrentToken();
        if (token != JSONToken.START_OBJECT && token != JSONToken.START_ARRAY) {
            return;
        }

        Integer depth = 1;
        while (depth > 0) {
            JSONToken nextToken = parser.nextToken();
            if (nextToken == null) {
                throw new PayloadException('Unexpected end of order payload.');
            }
            if (
                nextToken == JSONToken.START_OBJECT ||
                nextToken == JSONToken.START_ARRAY
            ) {
                depth++;
            } else if (
                nextToken == JSONToken.END_OBJECT ||
                nextToken == JSONToken.END_ARRAY
            ) {
                depth--;
            }
        }
    }
