public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option() {
        }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {
    }

    private static Map<String, Schema.SObjectType> objectTypesByLowerCaseName;

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new PicklistServiceException('Object API name must not be null or blank.');
            }
            if (String.isBlank(fieldApiName)) {
                throw new PicklistServiceException('Field API name must not be null or blank.');
            }

            String objectName = objectApiName.trim();
            String fieldName = fieldApiName.trim();

            Schema.SObjectType objectType = getObjectType(objectName);
            if (objectType == null) {
                throw new PicklistServiceException('Object not found: ' + objectName);
            }

            Schema.SObjectField fieldToken = getField(objectType, fieldName);
            if (fieldToken == null) {
                throw new PicklistServiceException(
                    'Field not found: ' + objectName + '.' + fieldName
                );
            }

            Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();
            if (
                fieldType != Schema.DisplayType.Picklist &&
                fieldType != Schema.DisplayType.MultiPicklist
            ) {
                throw new PicklistServiceException(
                    'Field is not a picklist or multi-select picklist: ' +
                    objectName + '.' + fieldName
                );
            }

            List<Option> options = new List<Option>();
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry == null || entry.isActive() != true) {
                    continue;
                }
                Option option = new Option();
                option.value = entry.getValue();
                option.label = entry.getLabel();
                option.isDefault = entry.isDefaultValue() == true;
                options.add(option);
            }
            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to retrieve picklist options: ' + e.getMessage()
            );
        }
    }

    private static Schema.SObjectType getObjectType(String objectName) {
        if (objectTypesByLowerCaseName == null) {
            objectTypesByLowerCaseName = new Map<String, Schema.SObjectType>();
            Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
            for (String apiName : globalDescribe.keySet()) {
                if (apiName != null) {
                    objectTypesByLowerCaseName.put(
                        apiName.toLowerCase(),
                        globalDescribe.get(apiName)
                    );
                }
            }
        }
        return objectTypesByLowerCaseName.get(objectName.toLowerCase());
    }

    private static Schema.SObjectField getField(
        Schema.SObjectType objectType,
        String fieldName
    ) {
        Map<String, Schema.SObjectField> fieldsByName =
            objectType.getDescribe().fields.getMap();
        for (String apiName : fieldsByName.keySet()) {
            if (apiName != null && apiName.equalsIgnoreCase(fieldName)) {
                return fieldsByName.get(apiName);
            }
        }
        return null;
    }
}
