public with sharing class AccountScoringJob implements Queueable {
    private static final Integer BATCH_SIZE = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null)
            ? new List<Id>()
            : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Integer i = 0; i < this.accountIds.size(); i++) {
            if (i < BATCH_SIZE) {
                batchIds.add(this.accountIds.get(i));
            } else {
                remainingIds.add(this.accountIds.get(i));
            }
        }

        Boolean finalizerAttached = false;

        // Enqueue the next link from a finalizer when this job is running
        // asynchronously. A job enqueued by a finalizer starts a new async
        // chain, so the Developer Edition chained-job stack-depth limit does
        // not stop a long chain. A direct call has no QueueableContext and
        // cannot attach a finalizer, so it falls back to enqueueing directly.
        if (context != null && !remainingIds.isEmpty()) {
            try {
                System.attachFinalizer(new ChainFinalizer(remainingIds));
                finalizerAttached = true;
            } catch (Exception attachException) {
                finalizerAttached = false;
            }
        }

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account account : accounts) {
            if (account.AnnualRevenue != null && account.AnnualRevenue >= HOT_THRESHOLD) {
                account.Rating = 'Hot';
            } else if (account.AnnualRevenue != null && account.AnnualRevenue >= WARM_THRESHOLD) {
                account.Rating = 'Warm';
            } else {
                account.Rating = 'Cold';
            }
        }

        update accounts;

        if (!remainingIds.isEmpty() && !finalizerAttached) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    private class ChainFinalizer implements Finalizer {
        private final List<Id> remainingIds;

        public ChainFinalizer(List<Id> remainingIds) {
            this.remainingIds = (remainingIds == null)
                ? new List<Id>()
                : new List<Id>(remainingIds);
        }

        public void execute(FinalizerContext context) {
            if (context != null && context.getResult() != ParentJobResult.SUCCESS) {
                return;
            }
            if (!this.remainingIds.isEmpty()) {
                System.enqueueJob(new AccountScoringJob(this.remainingIds));
            }
        }
    }
}
