public with sharing class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null
            ? new Set<Id>()
            : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        Boolean succeeded =
            context != null &&
            context.getResult() == ParentJobResult.SUCCESS;

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Status__c = succeeded ? 'Success' : 'Failed',
            Attempt__c = this.attempt
        );

        if (!succeeded) {
            Exception jobException = context == null
                ? null
                : context.getException();
            String errorMessage = jobException == null
                ? null
                : jobException.getMessage();

            if (errorMessage != null && errorMessage.length() > 255) {
                errorMessage = errorMessage.substring(0, 255);
            }

            jobLog.Error__c = errorMessage;
        }

        insert jobLog;

        if (!succeeded && this.attempt < 3) {
            System.enqueueJob(
                new ErpAccountSyncJob(this.accountIds, this.attempt + 1)
            );
        }
    }
}
