public without sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final Integer DIRECT_DELETE_LIMIT = 10000;
    private static final Integer PURGE_BATCH_SIZE = 2000;
    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String NIGHTLY_CRON = '0 0 2 * * ?';

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        Datetime nonErrorCutoff = Datetime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);
        Integer directDeleteLimit = DIRECT_DELETE_LIMIT;

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE
                (
                    CreatedDate < :nonErrorCutoff
                    AND (Level__c = null OR Level__c != 'ERROR')
                )
                OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
            ORDER BY CreatedDate ASC
            LIMIT :directDeleteLimit
        ];

        if (logsToDelete.isEmpty()) {
            return;
        }

        List<Id> logIdsToDelete = new List<Id>();
        for (FB_Integration_Log__c logToDelete : logsToDelete) {
            logIdsToDelete.add(logToDelete.Id);
        }

        delete logsToDelete;
        Database.emptyRecycleBin(logIdsToDelete);

        // If the direct-delete limit was reached, there may be more eligible
        // records than one transaction can safely remove. Use batch Apex to
        // remove the remainder; its QueryLocator is not subject to the
        // ordinary 50,000-row SOQL limit.
        if (logsToDelete.size() == DIRECT_DELETE_LIMIT) {
            Database.executeBatch(new LogPurgeJob(), PURGE_BATCH_SIZE);
        }
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        Datetime nonErrorCutoff = Datetime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        return Database.getQueryLocator(
            [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE
                    (
                        CreatedDate < :nonErrorCutoff
                        AND (Level__c = null OR Level__c != 'ERROR')
                    )
                    OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
            ]
        );
    }

    public void execute(Database.BatchableContext context, List<SObject> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        List<Id> scopeIds = new List<Id>();
        for (SObject recordToDelete : scope) {
            scopeIds.add(recordToDelete.Id);
        }

        delete scope;
        Database.emptyRecycleBin(scopeIds);
    }

    public void finish(Database.BatchableContext context) {
        // The QueryLocator in start() covers the entire eligible backlog,
        // so no chained job is required.
    }

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }
}
