    static void onInsert_blankLeadSource_defaultsToWeb() {
        List<Contact> contacts = new List<Contact>{
            new Contact(LastName = 'NullSource', LeadSource = null),
            new Contact(LastName = 'EmptySource', LeadSource = ''),
            new Contact(LastName = 'WhitespaceSource', LeadSource = '   ')
        };

        fflib_SObjectDomain.Test.Database.onInsert(contacts);
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        for (Contact c : contacts) {
            Assert.areEqual('Web', c.LeadSource,
                'A blank LeadSource must default to Web on insert.');
