        };

        fflib_SObjectDomain.Test.Database.onInsert(contacts);
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        Assert.areEqual('Phone Inquiry', contacts[0].LeadSource,
            'An existing LeadSource must not be overwritten on insert.');
        Assert.areEqual('Partner Referral', contacts[1].LeadSource,
            'An existing LeadSource must not be overwritten on insert.');
        Assert.areEqual('Purchased List', contacts[2].LeadSource,
            'An existing LeadSource must not be overwritten on insert.');
