/**
 * Cleans Contact phone numbers for a dialer that accepts only digits,
 * optionally preceded by a single leading '+'.
 *
 * Changes from the approach as originally described, and why:
 *
 * 1. '+' is kept only as a single leading sign, not wherever it appears.
 *    Keeping every '+' could produce values such as '44+20' or '++4420',
 *    which the dialer would still reject.
 *
 * 2. Only contacts whose phone actually changes are updated. Updating an
 *    already-clean number would needlessly fire validation rules, triggers
 *    and automations, change audit fields, and could report a validation
 *    failure for a record this cleanup did not need to touch.
 *
 * 3. The Id reported for a failed save is taken from the submitted record at
 *    the same position as its SaveResult, rather than from
 *    SaveResult.getId(), which is not reliable for failed operations.
 *    SaveResults are returned in the same order as the records submitted.
 *
 * 4. A phone containing no digits at all (for example '---') is left
 *    untouched rather than being blanked or reduced to a bare '+', neither
 *    of which is a dialable number; erasing it would silently destroy data.
 *
 * 5. The class runs 'with sharing' and in user mode, so record sharing,
 *    object permissions and field-level security are respected instead of
 *    being bypassed by Apex's default system-mode access. Updates are made
 *    through fresh Contact records carrying only Id and Phone, so no other
 *    (potentially stale) field values are written back.
 */
public with sharing class ContactPhoneCleanup {

    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
            AND Phone != null
            WITH USER_MODE
        ]) {
            if (String.isBlank(contact.Phone)) {
                continue;
            }

            String digitsAndPlusSigns = contact.Phone.replaceAll('[^0-9+]', '');
            Boolean hasLeadingPlus = digitsAndPlusSigns.startsWith('+');
            String digitsOnly = digitsAndPlusSigns.replace('+', '');

            if (digitsOnly.length() == 0) {
                continue;
            }

            String normalizedPhone = hasLeadingPlus ? '+' + digitsOnly : digitsOnly;

            if (normalizedPhone != contact.Phone) {
                contactsToUpdate.add(new Contact(Id = contact.Id, Phone = normalizedPhone));
            }
        }

        if (contactsToUpdate.isEmpty()) {
            return errorsByContactId;
        }

        List<Database.SaveResult> saveResults =
            Database.update(contactsToUpdate, false, AccessLevel.USER_MODE);

        for (Integer index = 0; index < saveResults.size(); index++) {
            Database.SaveResult saveResult = saveResults[index];

            if (saveResult.isSuccess()) {
                continue;
            }

            String firstErrorMessage = saveResult.getErrors().isEmpty()
                ? 'Unknown save error.'
                : saveResult.getErrors()[0].getMessage();

            errorsByContactId.put(contactsToUpdate[index].Id, firstErrorMessage);
        }

        return errorsByContactId;
    }
}
