/**
 * @description Aggregated opportunity totals for the weekly pipeline call.
 *
 * Deliberately implemented with a single GROUP BY aggregate query rather than
 * one SUM(Amount) query per stage inside a loop. Even though the managed stage
 * list currently contains four values, using one query:
 *   - consumes one SOQL query instead of four against the governor limit;
 *   - leaves headroom if this method is called in a bulk or chained context;
 *   - allows stages to be added without increasing the query count; and
 *   - avoids the SOQL-in-a-loop anti-pattern flagged by code scanners.
 */
public with sharing class PipelineSummary {
    private static final List<String> MANAGED_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    private class PipelineArgumentException extends Exception {
    }

    /**
     * @description Returns Amount totals for the four managed open stages.
     * @param fromDate first CloseDate to include.
     * @param toDate last CloseDate to include.
     * @return a map containing exactly the four managed stage keys; stages
     *         with no matching opportunities, or only null Amount values,
     *         map to 0 rather than null.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        if (fromDate == null || toDate == null) {
            throw new PipelineArgumentException('fromDate and toDate must not be null.');
        }

        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : MANAGED_STAGES) {
            totals.put(stage, Decimal.valueOf(0));
        }

        if (fromDate > toDate) {
            return totals;
        }

        for (AggregateResult result : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE
                StageName IN :MANAGED_STAGES
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ]) {
            String stageName = (String) result.get('StageName');
            Decimal totalAmount = (Decimal) result.get('totalAmount');

            if (stageName != null && totals.containsKey(stageName)) {
                totals.put(
                    stageName,
                    totalAmount == null ? Decimal.valueOf(0) : totalAmount
                );
            }
        }

        return totals;
    }
}
