/**
 * Sets Priority = 'High' on new Cases whose Account has Rating = 'Hot'.
 * All other Cases keep the Priority they were created with.
 *
 * Bulk-safe: Account IDs are collected first and queried once outside
 * the loop, so a batch of 200 Cases uses a single SOQL query instead
 * of up to 200 (which would exceed the governor limit).
 */
public with sharing class CasePriorityHandler {

    public static void handleBeforeInsert(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        for (Case c : newCases) {
            if (c.AccountId == null) {
                continue;
            }
            Account acc = accountsById.get(c.AccountId);
            if (acc != null && acc.Rating == 'Hot') {
                c.Priority = 'High';
            }
        }
    }
}
