/**
 * Pushes newly created Accounts to the ERP as customers.
 *
 * DEVIATION FROM THE REQUESTED DESIGN (deliberate, and required):
 *
 * 1. Asynchronous (Queueable), not a callout "right from the trigger".
 *    A trigger runs in the same transaction as the DML that fired it, so a
 *    synchronous callout here fails with
 *    "System.CalloutException: You have uncommitted work pending. Please
 *    commit or rollback before calling out", and could otherwise notify the
 *    ERP about Accounts whose transaction later rolls back. A Queueable job
 *    runs in its own transaction after the inserting transaction commits,
 *    so only genuinely created Accounts are sent, and only milliseconds
 *    later ("as soon as it is created" in practice).
 *
 * 2. One batched callout per trigger chunk, not one callout per Account.
 *    Apex allows at most 100 callouts per transaction, so the requested
 *    one-per-Account design would inevitably fail for the marketplace
 *    batches of up to 200 Accounts. The ERP endpoint is explicitly designed
 *    for this: it accepts a JSON array of 1-200 customers, which also matches
 *    the maximum trigger chunk size of 200. Traceability is preserved,
 *    because every Account remains a separate array element carrying its
 *    own 18-character salesforceId.
 *
 * Error handling and retries are out of scope for this ticket, so the
 * response (202 Accepted expected) is intentionally not processed.
 */
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private static final Integer MAX_CUSTOMERS_PER_REQUEST = 200;

    private final List<CustomerPayload> customers;

    public ErpCustomerSync(List<CustomerPayload> customers) {
        this.customers = customers == null ? new List<CustomerPayload>() : customers;
    }

    /**
     * Called from the after-insert trigger. Converts Trigger.new into
     * serialisable payloads (no SOQL needed) and enqueues one Queueable
     * job - i.e. one ERP callout - per batch of up to 200 customers.
     */
    public static void enqueue(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }
        List<CustomerPayload> batch = new List<CustomerPayload>();
        for (Account account : newAccounts) {
            batch.add(new CustomerPayload(
                // String.valueOf(Id) yields the 18-character form of the Id.
                String.valueOf(account.Id),
                account.Name,
                String.isBlank(account.BillingCountry) ? null : account.BillingCountry
            ));
            if (batch.size() == MAX_CUSTOMERS_PER_REQUEST) {
                System.enqueueJob(new ErpCustomerSync(batch));
                batch = new List<CustomerPayload>();
            }
        }
        if (!batch.isEmpty()) {
            System.enqueueJob(new ErpCustomerSync(batch));
        }
    }

    public void execute(QueueableContext context) {
        if (customers == null || customers.isEmpty()) {
            return;
        }
        HttpRequest request = new HttpRequest();
        request.setEndpoint('callout:ERP/api/customers');
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        // suppressApexObjectNulls = false, so a blank BillingCountry is sent
        // explicitly as "country": null rather than being omitted.
        request.setBody(JSON.serialize(customers, false));
        new Http().send(request);
    }

    /** One ERP customer; field names match the required JSON keys. */
    public class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(String salesforceId, String name, String country) {
            this.salesforceId = salesforceId;
            this.name = name;
            this.country = country;
        }
    }
}
