public with sharing class AccountRatingService {
    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Asynchronously recalculates the Rating for the supplied accounts.
     * Accepts a Set<Id> so callers can bulkify all accounts from a
     * transaction into a single future invocation.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        recalculateNow(accountIds);
    }

    /**
     * Synchronous implementation, separated from the @future method so it
     * can also be used when the caller is already in an asynchronous context.
     */
    public static void recalculateNow(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Set<Id> validAccountIds = new Set<Id>(accountIds);
        validAccountIds.remove(null);

        if (validAccountIds.isEmpty()) {
            return;
        }

        // Accounts with no open Opportunities will not appear in the
        // aggregate query below and therefore remain Cold.
        Map<Id, String> newRatingByAccountId = new Map<Id, String>();
        for (Id accountId : validAccountIds) {
            newRatingByAccountId.put(accountId, 'Cold');
        }

        for (AggregateResult result : [
            SELECT AccountId, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :validAccountIds
            AND IsClosed = false
            WITH USER_MODE
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Decimal maxAmount = (Decimal) result.get('maxAmount');

            newRatingByAccountId.put(
                accountId,
                maxAmount != null && maxAmount >= HOT_THRESHOLD ? 'Hot' : 'Warm'
            );
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account accountRecord : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :validAccountIds
            WITH USER_MODE
        ]) {
            String newRating = newRatingByAccountId.get(accountRecord.Id);

            if (accountRecord.Rating != newRating) {
                accountsToUpdate.add(
                    new Account(
                        Id = accountRecord.Id,
                        Rating = newRating
                    )
                );
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update as user accountsToUpdate;
        }
    }
}
