/**
 * Applies the PricingRules standard discount to new opportunity line items
 * that do not already have a discount.
 *
 * Deviation from the requested implementation, and why:
 * The Id-based PricingRules overload performs one SOQL query on every
 * invocation. Calling it once per line would therefore require up to
 * 200 queries for a single CPQ quote and exceed the synchronous SOQL
 * governor limit, rolling back the insert.
 *
 * Instead, this handler collects the distinct products in bulk, queries
 * them once, and delegates the family-to-discount decision to the
 * family-based PricingRules overload. The discount rules consequently
 * remain defined only in PricingRules: they are neither changed nor
 * copied into this class.
 *
 * OpportunityLineItem.Product2Id is derived from PricebookEntryId and may
 * not yet be populated in a before-insert trigger for lines created only
 * with a price book entry, so such lines are resolved through their
 * PricebookEntryId in one additional bulk query when needed.
 */
public with sharing class LineItemDiscountHandler {

    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        Set<Id> productIds = new Set<Id>();
        Set<Id> pricebookEntryIds = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            if (line == null || line.Discount != null) {
                continue;
            }
            if (line.Product2Id != null) {
                productIds.add(line.Product2Id);
            } else if (line.PricebookEntryId != null) {
                pricebookEntryIds.add(line.PricebookEntryId);
            }
        }

        if (productIds.isEmpty() && pricebookEntryIds.isEmpty()) {
            return;
        }

        Map<Id, Product2> productsById = new Map<Id, Product2>();
        if (!productIds.isEmpty()) {
            productsById = new Map<Id, Product2>([
                SELECT Id, Family
                FROM Product2
                WHERE Id IN :productIds
            ]);
        }

        Map<Id, PricebookEntry> entriesById = new Map<Id, PricebookEntry>();
        if (!pricebookEntryIds.isEmpty()) {
            entriesById = new Map<Id, PricebookEntry>([
                SELECT Id, Product2Id, Product2.Family
                FROM PricebookEntry
                WHERE Id IN :pricebookEntryIds
            ]);
        }

        for (OpportunityLineItem line : newLines) {
            // A non-null Discount, including 0, was supplied explicitly and is kept.
            if (line == null || line.Discount != null) {
                continue;
            }

            String family;
            Boolean productResolved = false;

            if (line.Product2Id != null && productsById.containsKey(line.Product2Id)) {
                family = productsById.get(line.Product2Id).Family;
                productResolved = true;
            } else if (line.PricebookEntryId != null && entriesById.containsKey(line.PricebookEntryId)) {
                family = entriesById.get(line.PricebookEntryId).Product2.Family;
                productResolved = true;
            }

            if (productResolved) {
                line.Discount = PricingRules.standardDiscountForFamily(family);
            }
        }
    }
}
