public with sharing class LeadContactMatcher {

    /**
     * Matches leads to contacts by normalized email.
     *
     * Deliberately NOT implemented as a nested loop:
     * 3,000 leads x 3,000 contacts is up to 9,000,000 comparisons in the
     * worst case (no match / match at the end), with the same emails being
     * re-trimmed and re-lowercased on every comparison. Inside an import
     * transaction that is already spending CPU on validation, triggers and
     * other processing, that risks hitting the Apex CPU time limit.
     *
     * Instead this builds one Map of normalized email -> first Contact Id
     * (O(contacts)), then looks each lead up in O(1) (O(leads)). Each email
     * is normalized exactly once, so total work is ~6,000 operations rather
     * than up to 9,000,000, with identical, deterministic results.
     *
     * No SOQL or DML is performed.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> results = new List<Id>();

        if (leads == null || leads.isEmpty()) {
            return results;
        }

        // Index contacts by normalized email, keeping the first contact
        // seen for each email address.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact contactRecord : contacts) {
                String normalizedEmail = normalizeEmail(contactRecord?.Email);
                if (normalizedEmail == null) {
                    continue;
                }
                if (!contactIdByEmail.containsKey(normalizedEmail)) {
                    contactIdByEmail.put(normalizedEmail, contactRecord.Id);
                }
            }
        }

        // Preserve input lead order and size, with null for no match.
        for (Lead leadRecord : leads) {
            String normalizedEmail = normalizeEmail(leadRecord?.Email);
            results.add(
                normalizedEmail == null
                    ? null
                    : contactIdByEmail.get(normalizedEmail)
            );
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
