public with sharing class CaseSurveyJob implements Queueable {
    private final Set<Id> caseIds;

    public CaseSurveyJob(Id caseId) {
        this(
            caseId == null
                ? new Set<Id>()
                : new Set<Id>{ caseId }
        );
    }

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = caseIds == null
            ? new Set<Id>()
            : new Set<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Task> tasks = new List<Task>();
        Date activityDate = Date.today().addDays(2);

        // Re-query because the Cases may have been reopened or their
        // contacts may have changed after the job was enqueued.
        for (Case closedCase : [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
              AND IsClosed = true
              AND ContactId != null
            WITH USER_MODE
        ]) {
            tasks.add(
                new Task(
                    WhatId = closedCase.Id,
                    WhoId = closedCase.ContactId,
                    Subject = 'CSAT survey: ' + closedCase.CaseNumber,
                    ActivityDate = activityDate,
                    Status = 'Not Started'
                )
            );
        }

        if (tasks.isEmpty()) {
            return;
        }

        // Partial success preserves failure isolation in the bulk job:
        // a failure for one Task does not roll back the other Tasks.
        Database.SaveResult[] results = Database.insert(
            tasks,
            false,
            AccessLevel.USER_MODE
        );

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                System.debug(
                    LoggingLevel.ERROR,
                    'CaseSurveyJob: Could not create survey task for Case ' +
                    tasks[i].WhatId +
                    ': ' +
                    results[i].getErrors()
                );
            }
        }
    }
}
