/**
 * Sends renewal reminder emails to Opportunity owners.
 *
 * Why Messaging.sendEmail is NOT called once per Opportunity:
 * - A transaction may make at most 10 Messaging.sendEmail invocations,
 *   regardless of how many messages each invocation contains
 *   (see Limits.getEmailInvocations()).
 * - A loop calling sendEmail for up to 200 Opportunities would attempt
 *   up to 200 invocations. The 11th invocation throws an uncatchable
 *   System.LimitException, aborting the transaction and the scheduled job,
 *   so the remaining reminders would never be sent.
 * - Fault isolation does not require one invocation per email. A single
 *   bulk invocation with allOrNone = false processes each message
 *   independently and returns one SendEmailResult per message. Failed
 *   messages therefore do not prevent the others from being sent.
 *
 * Targeting internal Users by Id remains appropriate: those emails do not
 * consume the org's daily allocation for external email. That exemption
 * does not, however, exempt the code from the 10-invocation governor limit.
 */
public with sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Avoid sending duplicate reminders for duplicate input Ids.
        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }
        if (uniqueOpportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueOpportunityIds
            WITH USER_MODE
        ];

        List<Messaging.SingleEmailMessage> emails =
            new List<Messaging.SingleEmailMessage>();

        for (Opportunity opportunity : opportunities) {
            if (opportunity.OwnerId == null) {
                continue;
            }

            String closeDateText = opportunity.CloseDate == null
                ? 'not set'
                : String.valueOf(opportunity.CloseDate);

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opportunity.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opportunity.Name);
            email.setPlainTextBody(
                'Hello,\n\n' +
                'The opportunity "' + opportunity.Name +
                '" is due for renewal.\n' +
                'Close date: ' + closeDateText + '\n\n' +
                'Please review the opportunity and take any required action.'
            );
            emails.add(email);
        }

        if (emails.isEmpty()) {
            return 0;
        }

        // One bulk invocation only. allOrNone = false gives the required
        // per-email fault isolation without exhausting email invocations.
        Messaging.SendEmailResult[] results = Messaging.sendEmail(emails, false);

        Integer sentCount = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                sentCount++;
            }
        }
        return sentCount;
    }
}
