/**
 * Keeps Contact.MailingCountry in sync when an Account moves headquarters.
 *
 * Deliberately does NOT load every Contact in the org: with ~2.3M contacts
 * that would breach the 50,000 SOQL row limit (and heap) and fail every
 * batch. Instead this performs a single selective query for contacts of
 * only those accounts whose BillingCountry changed in this trigger batch.
 */
public with sharing class AccountCountrySync {
    public static void handleAfterUpdate(
        List<Account> newAccounts,
        Map<Id, Account> oldAccountsById
    ) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccountsById == null) {
            return;
        }

        Map<Id, Account> changedAccountsById = new Map<Id, Account>();
        Map<Id, String> previousCountryByAccountId = new Map<Id, String>();
        Set<String> previousCountries = new Set<String>();

        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccountsById.get(newAccount.Id);
            if (oldAccount == null || newAccount.BillingCountry == oldAccount.BillingCountry) {
                continue;
            }
            changedAccountsById.put(newAccount.Id, newAccount);
            previousCountryByAccountId.put(newAccount.Id, oldAccount.BillingCountry);
            if (oldAccount.BillingCountry != null) {
                previousCountries.add(oldAccount.BillingCountry);
            }
        }

        // No BillingCountry changed: no query, no DML.
        if (changedAccountsById.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // The one and only query: selective on the indexed AccountId lookup,
        // returning at most the contacts of the changed accounts that are
        // blank or match some previous BillingCountry in this batch.
        for (Contact contact : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE
                AccountId IN :changedAccountsById.keySet()
                AND (MailingCountry = null OR MailingCountry IN :previousCountries)
            WITH USER_MODE
        ]) {
            String previousCountry = previousCountryByAccountId.get(contact.AccountId);

            // The SOQL IN clause matches previous countries across the whole
            // batch, so re-check against this contact's own account: a contact
            // whose MailingCountry equals *another* account's old country
            // (i.e. they work abroad) must be left alone.
            if (contact.MailingCountry != null && contact.MailingCountry != previousCountry) {
                continue;
            }

            String newCountry = changedAccountsById.get(contact.AccountId).BillingCountry;
            if (contact.MailingCountry == newCountry) {
                continue;
            }

            contact.MailingCountry = newCountry;
            contactsToUpdate.add(contact);
        }

        if (!contactsToUpdate.isEmpty()) {
            update as user contactsToUpdate;
        }
    }
}
