import { LightningElement, api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';

export default class AccountHeader extends LightningElement {
    @api recordId;

    @wire(getRecord, {
        recordId: '$recordId',
        fields: [
            'Account.Name',
            'Account.Industry',
            'Account.AnnualRevenue',
            'Account.Owner.Name'
        ]
    })
    account;

    get isLoading() {
        return !this.account?.data && !this.account?.error;
    }

    get errorMessage() {
        const error = this.account?.error;
        if (!error) {
            return '';
        }
        if (error.body?.message) {
            return error.body.message;
        }
        if (typeof error.body === 'string') {
            return error.body;
        }
        if (Array.isArray(error.body) && error.body[0]?.message) {
            return error.body[0].message;
        }
        return error.message || '';
    }

    get accountName() {
        return this.resolveField('Name');
    }

    get industry() {
        return this.resolveField('Industry');
    }

    get annualRevenue() {
        return this.resolveField('AnnualRevenue');
    }

    get ownerName() {
        const data = this.account?.data;
        if (!data) {
            return undefined;
        }

        const fields = data.fields;
        const owner =
            fields?.Owner ??
            fields?.['Account.Owner'] ??
            fields?.['Owner.Name'] ??
            fields?.OwnerName;

        if (typeof owner === 'string') {
            return owner;
        }

        if (owner && typeof owner === 'object') {
            const nestedName = owner.fields?.Name ?? owner.fields?.['Owner.Name'];
            if (nestedName != null) {
                return typeof nestedName === 'object' && 'value' in nestedName
                    ? nestedName.value
                    : nestedName;
            }

            const ownerValue = owner.value;
            if (typeof ownerValue === 'string') {
                return ownerValue;
            }
            if (ownerValue && typeof ownerValue === 'object') {
                const valueName = ownerValue.fields?.Name ?? ownerValue.Name;
                if (valueName != null) {
                    return typeof valueName === 'object' && 'value' in valueName
                        ? valueName.value
                        : valueName;
                }
            }

            if (owner.Name != null) {
                return typeof owner.Name === 'object' && 'value' in owner.Name
                    ? owner.Name.value
                    : owner.Name;
            }

            if (owner.displayValue) {
                return owner.displayValue;
            }
        }

        try {
            return typeof getFieldValue === 'function'
                ? getFieldValue(data, 'Account.Owner.Name')
                : undefined;
        } catch (error) {
            return undefined;
        }
    }

    resolveField(fieldName) {
        const data = this.account?.data;
        if (!data) {
            return undefined;
        }

        const fields = data.fields;
        if (fields) {
            const field = fields[fieldName] ?? fields[`Account.${fieldName}`];
            if (field != null) {
                if (typeof field === 'object') {
                    return 'value' in field ? field.value : field;
                }
                return field;
            }
        } else if (data[fieldName] != null) {
            const field = data[fieldName];
            return typeof field === 'object' && 'value' in field
                ? field.value
                : field;
        }

        try {
            return typeof getFieldValue === 'function'
                ? getFieldValue(data, `Account.${fieldName}`)
                : undefined;
        } catch (error) {
            return undefined;
        }
    }
}
