import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];

    showError = false;

    handleReset() {
        this.template
            .querySelectorAll('c-line-item-editor')
            .forEach((editor) => {
                editor.reset();
            });
    }

    handleSubmit() {
        const editors = [
            ...this.template.querySelectorAll('c-line-item-editor')
        ];

        // Map (not every/some) so every editor is validated, even after a failure.
        const validity = editors.map((editor) => editor.validate());
        const allValid = validity.every(Boolean);

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;
        const lines = editors.map((editor) => editor.getValue());
        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines },
