import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;
    hasStats = false;

    _intervalId = null;
    _isLoading = false;
    _visibilityChangeHandler;

    constructor() {
        super();
        this._visibilityChangeHandler = this.handleVisibilityChange.bind(this);
    }

    connectedCallback() {
        document.addEventListener(
            'visibilitychange',
            this._visibilityChangeHandler
        );

        if (document.visibilityState !== 'hidden') {
            this.loadStats();
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener(
            'visibilitychange',
            this._visibilityChangeHandler
        );
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            this.loadStats();
            this.startPolling();
        }
    }

    startPolling() {
        this.stopPolling();
        this._intervalId = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    async loadStats() {
        if (this._isLoading) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            return;
        }

        this._isLoading = true;
        try {
            const result = await getQueueStats();
            this.waiting = result.waiting;
            this.longestWaitMinutes = result.longestWaitMinutes;
            this.hasStats = true;
            this.errorMessage = undefined;
        } catch (error) {
            this.errorMessage = error?.body?.message;
        } finally {
            this._isLoading = false;
        }
    }
}
