import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_EMAIL_DOMAINS = [
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleFullNameChange(event) {
        this.fullName = event.detail.value;
    }

    handleEmailChange(event) {
        this.email = event.detail.value;
    }

    handleCompanyChange(event) {
        this.company = event.detail.value;
    }

    async handleRegister() {
        const emailInput = this.template.querySelector(
            '[data-field="email"]'
        );
        const emailDomain = (this.email || '')
            .trim()
            .toLowerCase()
            .split('@')
            .pop();
        const isBlockedDomain = BLOCKED_EMAIL_DOMAINS.includes(emailDomain);

        if (emailInput) {
            emailInput.setCustomValidity(
                isBlockedDomain ? 'Use your work email address.' : ''
            );
        }

        let isValid = !isBlockedDomain;
        this.template
            .querySelectorAll('lightning-input')
            .forEach((input) => {
                const validity = input.reportValidity();
                if (validity === false) {
                    isValid = false;
                } else if (
                    validity === undefined &&
                    typeof input.checkValidity === 'function' &&
                    input.checkValidity() === false
                ) {
                    isValid = false;
                }
            });

        if (!isValid) {
            return;
        }

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        }
    }
