import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _value;
    _options = [];
    _activeIndex = 0;

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue;
        this._syncActiveToValue();
    }

    @api
    get options() {
        return this._options;
    }

    set options(newOptions) {
        this._options = Array.isArray(newOptions) ? newOptions : [];
        this._syncActiveToValue();
    }

    get decoratedOptions() {
        return this._options.map((option, index) => ({
            value: option.value,
            label: option.label,
            id: `option-${index}`,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    get activeId() {
        if (this._options.length === 0) {
            return '';
        }
        return `option-${this._clampedActiveIndex()}`;
    }

    _clampedActiveIndex() {
        if (this._options.length === 0) {
            return 0;
        }
        return Math.min(
            Math.max(this._activeIndex, 0),
            this._options.length - 1
        );
    }

    _syncActiveToValue() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );
        this._activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
    }

    handleKeyDown(event) {
        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                if (this._options.length > 0) {
                    this._activeIndex = Math.min(
                        this._clampedActiveIndex() + 1,
                        this._options.length - 1
                    );
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (this._options.length > 0) {
                    this._activeIndex = Math.max(
                        this._clampedActiveIndex() - 1,
                        0
                    );
                }
                break;
            case 'Home':
                event.preventDefault();
                if (this._options.length > 0) {
                    this._activeIndex = 0;
                }
                break;
            case 'End':
                event.preventDefault();
                if (this._options.length > 0) {
                    this._activeIndex = this._options.length - 1;
                }
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                if (this._options.length > 0) {
                    const activeOption =
                        this._options[this._clampedActiveIndex()];
                    if (activeOption) {
                        this._selectValue(activeOption.value);
                    }
                }
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const value = event.currentTarget.dataset.value;
        const index = this._options.findIndex(
            (option) => option.value === value
        );
        if (index >= 0) {
            this._activeIndex = index;
            this._selectValue(this._options[index].value);
        }
    }

    _selectValue(value) {
        if (value === this._value) {
            return;
        }
        this._value = value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true
            })
        );
    }
}
