import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = value;
        this.items = Array.isArray(value) ? value.map((task) => ({ ...task })) : [];
    }

    get displayHeading() {
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        const detailValue = event && event.detail ? event.detail.value : undefined;
        const targetValue = event && event.target ? event.target.value : undefined;
        const value =
            detailValue !== undefined && detailValue !== null ? detailValue : targetValue;
        this.newLabel = value !== undefined && value !== null ? String(value) : '';
    }

    handleAdd() {
        const input = this.template ? this.template.querySelector('.new-task') : null;

        let label = this.newLabel ? this.newLabel.trim() : '';
        if (!label && input && typeof input.value === 'string') {
            label = input.value.trim();
        }
        if (!label) {
            return;
        }

        let id = `new-${this.nextId++}`;
        while (this.items.some((task) => String(task.id) === id)) {
            id = `new-${this.nextId++}`;
        }

        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';
        if (input) {
            input.value = '';
        }

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const target = event ? event.target : null;
        let id = target && target.dataset ? target.dataset.id : undefined;

        if (
            (id === undefined || id === null) &&
            target &&
            typeof target.closest === 'function'
        ) {
            const elementWithId = target.closest('[data-id]');
            id = elementWithId && elementWithId.dataset ? elementWithId.dataset.id : undefined;
        }

        if (id === undefined || id === null) {
            return;
        }

        this.items = this.items.map((task) =>
            String(task.id) === String(id) ? { ...task, done: !task.done } : task
        );
    }
}
