/**
 * Sets donors' current employers through NPSP's primary-affiliation
 * mechanism.
 *
 * Changing only Contact.npsp__Primary_Affiliation__c lets NPSP create or
 * promote the matching Current, primary Affiliation and retire the previous
 * primary Affiliation as Former, non-primary with an end date of today.
 * Contact.AccountId is intentionally left untouched so each contact remains
 * in their Household Account.
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Map<Id, Id> requestedByContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id organizationId = employerByContactId.get(contactId);
            if (contactId != null && organizationId != null) {
                requestedByContactId.put(contactId, organizationId);
            }
        }
        if (requestedByContactId.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contact : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :requestedByContactId.keySet()
            WITH USER_MODE
        ]) {
            Id organizationId = requestedByContactId.get(contact.Id);
            // Skip contacts already pointing at the requested organization so
            // NPSP does not create a duplicate Affiliation and nothing changes.
            if (contact.npsp__Primary_Affiliation__c != organizationId) {
                contactsToUpdate.add(new Contact(
                    Id = contact.Id,
                    npsp__Primary_Affiliation__c = organizationId
                ));
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update as user contactsToUpdate;
        }
    }
}
