public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation is required.');
        }

        Set<Id> gauIds = percentByGauId.keySet();
        Decimal totalPercent = 0;

        for (Id gauId : gauIds) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id is required for every allocation.');
            }

            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException(
                    'Every allocation percentage must be greater than zero.'
                );
            }
            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Allocation percentages cannot total more than 100%.'
            );
        }

        List<Opportunity> opportunities = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }

        Map<Id, npsp__General_Accounting_Unit__c> gausById =
            new Map<Id, npsp__General_Accounting_Unit__c>([
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
                WITH USER_MODE
            ]);

        if (gausById.size() != gauIds.size()) {
            throw new AllocationException(
                'One or more General Accounting Units were not found.'
            );
        }

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit is inactive: ' +
                    gau.Name + ' (' + gau.Id + ')'
                );
            }
        }

        // All validation is complete before any data is changed.

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            AND npsp__Payment__c = null
            AND npsp__Campaign__c = null
            AND npsp__Recurring_Donation__c = null
            WITH USER_MODE
        ];

        if (!existingAllocations.isEmpty()) {
            delete as user existingAllocations;
        }

        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            allocations.add(
                new npsp__Allocation__c(
                    npsp__Opportunity__c = opportunityId,
                    npsp__General_Accounting_Unit__c = gauId,
                    npsp__Percent__c = percentByGauId.get(gauId)
                    // npsp__Amount__c is intentionally not set. NPSP derives
                    // the amount from the percentage and keeps it correct
                    // when the Opportunity amount subsequently changes.
                )
            );
        }

        insert as user allocations;

        Set<Id> insertedIds = new Set<Id>();
        for (npsp__Allocation__c allocation : allocations) {
            insertedIds.add(allocation.Id);
        }

        Map<Id, npsp__Allocation__c> persistedById =
            new Map<Id, npsp__Allocation__c>([
                SELECT
                    Id,
                    npsp__Opportunity__c,
                    npsp__General_Accounting_Unit__c,
                    npsp__Amount__c,
                    npsp__Percent__c,
                    npsp__Payment__c,
                    npsp__Campaign__c,
                    npsp__Recurring_Donation__c
                FROM npsp__Allocation__c
                WHERE Id IN :insertedIds
                WITH USER_MODE
            ]);

        List<npsp__Allocation__c> result = new List<npsp__Allocation__c>();
        for (npsp__Allocation__c allocation : allocations) {
            npsp__Allocation__c persisted = persistedById.get(allocation.Id);
            result.add(persisted != null ? persisted : allocation);
        }
        return result;
    }
}
