        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'At least one household member is required.'
            );
        }

        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException(
                    'Household members must not contain null contacts.'
                );
            }
        }

        Schema.RecordTypeInfo householdRecordType = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName()
            .get(HOUSEHOLD_ACCOUNT_DEVELOPER_NAME);

        if (householdRecordType == null) {
            throw new IllegalArgumentException(
                'The HH_Account Account record type could not be found.'
            );
        }

        // Intentionally leave the account name unset. With automatic
        // household naming enabled, NPSP supplies the initial household
        // name and generates the household name and greetings as contacts
        // are added.
        Account household = new Account(
            RecordTypeId = householdRecordType.getRecordTypeId()
        );
        insert household;

        // Insert the primary member first so that NPSP establishes the
        // household with that contact before the other members are added.
        // Giving every contact this AccountId also prevents NPSP from
        // creating a separate household for any of them.
        Contact primaryContact = members[0];
        primaryContact.AccountId = household.Id;
        insert primaryContact;

        List<Contact> remainingMembers = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            members[i].AccountId = household.Id;
            remainingMembers.add(members[i]);
        }
        if (!remainingMembers.isEmpty()) {
            insert remainingMembers;
        }

        // Explicitly ensure that the first supplied member, rather than
        // any contact NPSP might select during contact processing, is the
        // household's primary contact.
        update new Account(
            Id = household.Id,
            npe01__One2OneContact__c = primaryContact.Id
        );

        return household.Id;
    }
}
