public with sharing class SoftCreditService {
    public class SoftCreditException extends Exception {
    }

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> requestedPairs = new Set<String>();

        // Validate fields that do not require a query, and collect lookup keys.
        for (SoftCreditRequest request : requests) {
            if (request == null) {
                throw new SoftCreditException('Soft credit request must not be null.');
            }
            if (request.opportunityId == null) {
                throw new SoftCreditException(
                    'Soft credit request must specify an opportunity.'
                );
            }
            if (request.contactId == null) {
                throw new SoftCreditException(
                    'Soft credit request must specify a contact.'
                );
            }
            if (request.amount == null || request.amount <= 0) {
                throw new SoftCreditException(
                    'Soft credit amount must be greater than zero.'
                );
            }
            if (String.isBlank(request.role)) {
                throw new SoftCreditException(
                    'Soft credit request must specify a role.'
                );
            }

            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
            requestedPairs.add(pairKey(request.opportunityId, request.contactId));
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
            WITH USER_MODE
        ]);

        // Validate the whole call against the opportunities before any DML.
        for (SoftCreditRequest request : requests) {
            Opportunity opportunity = opportunitiesById.get(request.opportunityId);
            if (opportunity == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + request.opportunityId
                );
            }
            if (request.contactId == opportunity.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'A partial soft credit cannot be given to the primary contact.'
                );
            }
            if (opportunity.Amount == null || request.amount > opportunity.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount cannot exceed the opportunity amount.'
                );
            }
        }

        // npsp__Contact_Name__c is populated only when it is a writable field
        // in this org. Formula or otherwise calculated fields are left alone.
        Schema.DescribeFieldResult contactNameField = describeContactNameField();
        Boolean populateContactNameAsText = isWritableTextField(contactNameField);
        Boolean populateContactNameAsReference =
            isWritableContactReference(contactNameField);

        Map<Id, Contact> contactsById = new Map<Id, Contact>();
        if (populateContactNameAsText) {
            contactsById = new Map<Id, Contact>([
                SELECT Id, Name
                FROM Contact
                WHERE Id IN :contactIds
                WITH USER_MODE
            ]);
        }

        Map<String, OpportunityContactRole> contactRoleByPair =
            new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> duplicateContactRoles =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole contactRole : [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
            AND ContactId IN :contactIds
            WITH USER_MODE
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            String key = pairKey(contactRole.OpportunityId, contactRole.ContactId);
            if (!requestedPairs.contains(key)) {
                continue;
            }
            if (contactRoleByPair.containsKey(key)) {
                duplicateContactRoles.add(contactRole);
            } else {
                contactRoleByPair.put(key, contactRole);
            }
        }

        Map<String, npsp__Partial_Soft_Credit__c> softCreditByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> duplicateSoftCredits =
            new List<npsp__Partial_Soft_Credit__c>();

        for (npsp__Partial_Soft_Credit__c softCredit : [
            SELECT
                Id,
                npsp__Opportunity__c,
                npsp__Contact__c,
                npsp__Amount__c,
                npsp__Role_Name__c,
                npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
            AND npsp__Contact__c IN :contactIds
            WITH USER_MODE
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            String key = pairKey(
                softCredit.npsp__Opportunity__c,
                softCredit.npsp__Contact__c
            );
            if (!requestedPairs.contains(key)) {
                continue;
            }
            if (softCreditByPair.containsKey(key)) {
                duplicateSoftCredits.add(softCredit);
            } else {
                softCreditByPair.put(key, softCredit);
            }
        }

        // Reuse an existing contact role whenever one exists, changing its
        // role rather than creating a second role for the same pair.
        List<OpportunityContactRole> contactRolesToUpsert =
            new List<OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            OpportunityContactRole contactRole = contactRoleByPair.get(key);

            if (contactRole == null) {
                contactRole = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role,
                    IsPrimary = false
                );
                contactRoleByPair.put(key, contactRole);
            } else {
                contactRole.Role = request.role;
            }
            contactRolesToUpsert.add(contactRole);
        }

        if (!contactRolesToUpsert.isEmpty()) {
            upsert as user contactRolesToUpsert;
        }

        // Contact roles now all have Ids, so soft credits can be linked to
        // the exact role that carries the requested role name.
        List<npsp__Partial_Soft_Credit__c> softCreditsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            OpportunityContactRole contactRole = contactRoleByPair.get(key);
            npsp__Partial_Soft_Credit__c softCredit = softCreditByPair.get(key);

            if (softCredit == null) {
                softCredit = new npsp__Partial_Soft_Credit__c();
                softCreditByPair.put(key, softCredit);
            }

            softCredit.npsp__Opportunity__c = request.opportunityId;
            softCredit.npsp__Contact__c = request.contactId;
            softCredit.npsp__Amount__c = request.amount;
            softCredit.npsp__Role_Name__c = request.role;
            softCredit.npsp__Contact_Role_ID__c = String.valueOf(contactRole.Id);

            if (populateContactNameAsReference) {
                softCredit.put('npsp__Contact_Name__c', request.contactId);
            } else if (populateContactNameAsText) {
                Contact contact = contactsById.get(request.contactId);
                if (contact != null && String.isNotBlank(contact.Name)) {
                    String contactName = contact.Name;
                    Integer maxLength = contactNameField.getLength();
                    if (
                        maxLength != null &&
                        maxLength > 0 &&
                        contactName.length() > maxLength
                    ) {
                        contactName = contactName.substring(0, maxLength);
                    }
                    softCredit.put('npsp__Contact_Name__c', contactName);
                }
            }

            softCreditsToUpsert.add(softCredit);
        }

        if (!softCreditsToUpsert.isEmpty()) {
            upsert as user softCreditsToUpsert;
        }

        // Remove duplicates only after the retained records have been saved
        // and the retained soft credit points at the retained contact role.
        if (!duplicateContactRoles.isEmpty()) {
            delete as user duplicateContactRoles;
        }
        if (!duplicateSoftCredits.isEmpty()) {
            delete as user duplicateSoftCredits;
        }
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '|' + String.valueOf(contactId);
    }

    private static Schema.DescribeFieldResult describeContactNameField() {
        Map<String, Schema.SObjectField> fieldsByName =
            npsp__Partial_Soft_Credit__c.SObjectType.getDescribe()
                .fields.getMap();
        Schema.SObjectField contactNameToken = fieldsByName.get(
            'npsp__contact_name__c'
        );
        return contactNameToken == null ? null : contactNameToken.getDescribe();
    }

    private static Boolean isWritableTextField(
        Schema.DescribeFieldResult field
    ) {
        return field != null &&
            !field.isCalculated() &&
            field.isCreateable() &&
            field.isUpdateable() &&
            (
                field.getType() == Schema.DisplayType.STRING ||
                field.getType() == Schema.DisplayType.TEXTAREA
            );
    }

    private static Boolean isWritableContactReference(
        Schema.DescribeFieldResult field
    ) {
        if (
            field == null ||
            field.isCalculated() ||
            !field.isCreateable() ||
            !field.isUpdateable() ||
            field.getType() != Schema.DisplayType.REFERENCE
        ) {
            return false;
        }

        for (Schema.SObjectType referencedType : field.getReferenceTo()) {
            if (referencedType == Contact.SObjectType) {
                return true;
            }
        }
        return false;
    }
}
