/**
 * Records donations in a way that is compatible with NPSP.
 *
 * NPSP automation can create an OpportunityContactRole for the primary
 * contact, contact roles for household members, and a payment when an
 * Opportunity is inserted. This service therefore reconciles the records
 * created by that automation instead of blindly inserting a second set.
 */
public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact does not exist: null');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Gift amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact donor = donors[0];

        List<Contact> householdMembers = getHouseholdMembers(donor);

        Opportunity gift = new Opportunity(
            Name = buildOpportunityName(donor, giftDate),
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won'
        );
        insert gift;

        reconcileContactRoles(gift.Id, donor.Id, householdMembers);
        ensurePrimaryContact(gift.Id, donor.Id);
        reconcilePayment(gift.Id, amount, giftDate);

        return gift.Id;
    }

    private static List<Contact> getHouseholdMembers(Contact donor) {
        List<Contact> householdMembers;

        if (donor.AccountId == null) {
            householdMembers = new List<Contact>();
        } else {
            householdMembers = [
                SELECT Id
                FROM Contact
                WHERE AccountId = :donor.AccountId
                ORDER BY CreatedDate ASC, Id ASC
            ];
        }

        Boolean donorIncluded = false;
        for (Contact member : householdMembers) {
            if (member.Id == donor.Id) {
                donorIncluded = true;
                break;
            }
        }
        if (!donorIncluded) {
            householdMembers.add(new Contact(Id = donor.Id));
        }

        return householdMembers;
    }

    private static void reconcileContactRoles(
        Id opportunityId,
        Id donorContactId,
        List<Contact> householdMembers
    ) {
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            ORDER BY IsPrimary DESC, CreatedDate ASC, Id ASC
        ];

        Map<Id, OpportunityContactRole> roleByContactId =
            new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> duplicateRoles =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole existingRole : existingRoles) {
            if (roleByContactId.containsKey(existingRole.ContactId)) {
                duplicateRoles.add(existingRole);
            } else {
                roleByContactId.put(existingRole.ContactId, existingRole);
            }
        }

        List<OpportunityContactRole> rolesToInsert =
            new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate =
            new List<OpportunityContactRole>();

        for (Contact member : householdMembers) {
            Boolean isDonor = member.Id == donorContactId;
            String desiredRole = isDonor ? 'Donor' : 'Household Member';
            OpportunityContactRole existingRole = roleByContactId.get(member.Id);

            if (existingRole == null) {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = member.Id,
                    Role = desiredRole,
                    IsPrimary = isDonor
                ));
            } else if (
                existingRole.Role != desiredRole ||
                existingRole.IsPrimary != isDonor
            ) {
                existingRole.Role = desiredRole;
                existingRole.IsPrimary = isDonor;
                rolesToUpdate.add(existingRole);
            }
        }

        // Insert first so that any NPSP automation fired by a later update
        // can see that the household roles already exist.
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!duplicateRoles.isEmpty()) {
            delete duplicateRoles;
        }
    }

    private static void ensurePrimaryContact(Id opportunityId, Id donorContactId) {
        Opportunity gift = [
            SELECT Id, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (gift.npsp__Primary_Contact__c != donorContactId) {
            gift.npsp__Primary_Contact__c = donorContactId;
            update gift;
        }
    }

    private static void reconcilePayment(
        Id opportunityId,
        Decimal amount,
        Date giftDate
    ) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT
                Id,
                npe01__Payment_Amount__c,
                npe01__Payment_Date__c,
                npe01__Scheduled_Date__c,
                npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate ASC, Id ASC
        ];

        if (existingPayments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        npe01__OppPayment__c payment = existingPayments[0];
        if (
            payment.npe01__Payment_Amount__c != amount ||
            payment.npe01__Payment_Date__c != giftDate ||
            payment.npe01__Scheduled_Date__c != giftDate ||
            payment.npe01__Paid__c != true
        ) {
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Scheduled_Date__c = giftDate;
            payment.npe01__Paid__c = true;
            update payment;
        }

        if (existingPayments.size() > 1) {
            List<npe01__OppPayment__c> duplicatePayments =
                new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < existingPayments.size(); i++) {
                duplicatePayments.add(existingPayments[i]);
            }
            delete duplicatePayments;
        }
    }

    private static String buildOpportunityName(Contact donor, Date giftDate) {
        List<String> nameParts = new List<String>();
        if (String.isNotBlank(donor.FirstName)) {
            nameParts.add(donor.FirstName.trim());
        }
        if (String.isNotBlank(donor.LastName)) {
            nameParts.add(donor.LastName.trim());
        }

        String donorName = String.join(nameParts, ' ');
        String opportunityName =
            (String.isBlank(donorName) ? 'Donation ' : donorName + ' Donation ') +
            formatDate(giftDate);

        if (opportunityName.length() > 120) {
            opportunityName = opportunityName.substring(0, 120);
        }
        return opportunityName;
    }

    private static String formatDate(Date giftDate) {
        return String.valueOf(giftDate.year()) + '-' +
            String.valueOf(giftDate.month()).leftPad(2, '0') + '-' +
            String.valueOf(giftDate.day()).leftPad(2, '0');
    }
}
