public with sharing class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null && childId != parentId) {
                contactIds.add(childId);
                contactIds.add(parentId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // One query for every pair. Adding both directions below means an
        // existing record in either direction causes the pair to be skipped.
        Set<String> knownPairKeys = new Set<String>();
        for (npe4__Relationship__c existing : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
            AND npe4__RelatedContact__c IN :contactIds
        ]) {
            knownPairKeys.add(pairKey(existing.npe4__Contact__c, existing.npe4__RelatedContact__c));
            knownPairKeys.add(pairKey(existing.npe4__RelatedContact__c, existing.npe4__Contact__c));
        }

        List<npe4__Relationship__c> relationships = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String key = pairKey(childId, parentId);
            if (knownPairKeys.contains(key)) {
                continue;
            }
            knownPairKeys.add(key);
            knownPairKeys.add(pairKey(parentId, childId));

            // Create only the child's side. With NPSP's List Setting
            // reciprocal method, NPSP creates the parent-side reciprocal,
            // using Son, Daughter or Child from the Parent lookup according
            // to the child. Creating both sides here would create duplicates.
            relationships.add(
                new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = 'Parent',
                    npe4__Status__c = 'Current'
                )
            );
        }

        if (!relationships.isEmpty()) {
            insert relationships;
        }
    }

    private static String pairKey(Id firstId, Id secondId) {
        return String.valueOf(firstId) + '|' + String.valueOf(secondId);
    }
}
