```apex
public with sharing class RecordAccessService {
    // Salesforce allows a maximum of 200 RecordId values in a single
    // UserRecordAccess query. Querying more than 200 throws a QueryException.
    private static final Integer MAX_RECORD_IDS_PER_QUERY = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        List<Id> idsToCheck = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                idsToCheck.add(recordId);
            }
        }

        if (idsToCheck.isEmpty()) {
            return editable;
        }

        Id runningUserId = UserInfo.getUserId();

        // 2,000 IDs require at most 10 queries at 200 IDs per query.
        // UserRecordAccess supports mixed object types in the same query.
        for (Integer start = 0; start < idsToCheck.size(); start += MAX_RECORD_IDS_PER_QUERY) {
            Integer finish = Math.min(start + MAX_RECORD_IDS_PER_QUERY, idsToCheck.size());
            List<Id> chunk = new List<Id>();

            for (Integer i = start; i < finish; i++) {
                chunk.add(idsToCheck[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :runningUserId
                  AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
