/**
 * Employee directory service.
 *
 * Sharing is enforced by `with sharing`. Object and field access are
 * enforced explicitly because a plain SOQL query in Apex does not
 * enforce field-level security, while WITH SECURITY_ENFORCED or
 * USER_MODE would throw when a field is inaccessible instead of
 * returning the readable fields.
 */
public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {
        // No object-level read access: return no records rather than throw.
        if (!FB_Employee__c.SObjectType.getDescribe().isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Only select a custom field when the running user can read it.
        // Fields that are never selected are absent from the returned
        // SObjects (not present in their populated-fields map), rather
        // than being present with a null value.
        List<String> selectFields = new List<String>{ 'Id', 'Name' };

        if (FB_Employee__c.Department__c.getDescribe().isAccessible()) {
            selectFields.add('Department__c');
        }
        if (FB_Employee__c.Salary__c.getDescribe().isAccessible()) {
            selectFields.add('Salary__c');
        }
        if (FB_Employee__c.Personal_Email__c.getDescribe().isAccessible()) {
            selectFields.add('Personal_Email__c');
        }

        // The query is built only from compile-time field names checked
        // above; it contains no user-supplied input. Executed from this
        // `with sharing` class, it returns only records accessible to
        // the running user through sharing.
        String query =
            'SELECT ' + String.join(selectFields, ', ') +
            ' FROM FB_Employee__c' +
            ' ORDER BY Name ASC';

        return (List<FB_Employee__c>) Database.query(query);
    }
}
