public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    private static final Set<String> CUSTOMER_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> onboardingTasks = new List<Task>();
        Date activityDate = Date.today().addDays(7);

        for (SObject record : triggerNew) {
            Account accountRecord = (Account) record;

            if (!CUSTOMER_TYPES.contains(accountRecord.Type)) {
                continue;
            }

            onboardingTasks.add(
                new Task(
                    Subject = 'Onboard new customer',
                    WhatId = accountRecord.Id,
                    OwnerId = accountRecord.OwnerId,
                    ActivityDate = activityDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                )
            );
        }

        if (!onboardingTasks.isEmpty()) {
            insert onboardingTasks;
        }
    }
}
