/**
 * Imports contacts migrated from the legacy system.
 *
 * Migrated contacts are existing customers, so the welcome-task trigger
 * action is bypassed for this import only. All other Contact automation,
 * including phone formatting, continues to run.
 */
public with sharing class ContactImportService {
    private static final String CREATE_WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Bypass only this action, not Contact automation as a whole.
        MetadataTriggerHandler.bypass(CREATE_WELCOME_TASK_ACTION);
        try {
            insert contacts;
        } finally {
            // Always remove only this bypass, even if the insert fails,
            // so later inserts in the same transaction run normally and
            // any unrelated bypasses set by callers remain untouched.
            MetadataTriggerHandler.clearBypass(CREATE_WELCOME_TASK_ACTION);
        }
    }
}
