/**
 * Service for reassigning Accounts and their related Contacts to a new owner.
 */
public inherited sharing class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        TriggerBase.bypass(Account.SObjectType);
        try {
            List<Account> accountsToUpdate = [
                SELECT Id, OwnerId
                FROM Account
                WHERE Id IN :accountIds
            ];
            for (Account accountRecord : accountsToUpdate) {
                accountRecord.OwnerId = newOwnerId;
            }
            update accountsToUpdate;

            List<Contact> contactsToUpdate = [
                SELECT Id, OwnerId
                FROM Contact
                WHERE AccountId IN :accountIds
            ];
            for (Contact contactRecord : contactsToUpdate) {
                contactRecord.OwnerId = newOwnerId;
            }
            update contactsToUpdate;
        } finally {
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
