public with sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        preventDuplicateEmails((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldContactById = new Map<Id, Contact>();
        for (Contact oldContact : (List<Contact>) triggerOld) {
            oldContactById.put(oldContact.Id, oldContact);
        }
        preventDuplicateEmails((List<Contact>) triggerNew, oldContactById);
    }

    private void preventDuplicateEmails(
        List<Contact> newContacts,
        Map<Id, Contact> oldContactById
    ) {
        List<Contact> contactsToCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> normalizedEmails = new Set<String>();
        Set<Id> contactIdsToCheck = new Set<Id>();

        for (Contact newContact : newContacts) {
            if (newContact.AccountId == null || String.isBlank(newContact.Email)) {
                continue;
            }

            if (oldContactById != null) {
                Contact oldContact = oldContactById.get(newContact.Id);
                if (
                    oldContact != null &&
                    newContact.AccountId == oldContact.AccountId &&
                    normalizeEmail(newContact.Email) == normalizeEmail(oldContact.Email)
                ) {
                    continue;
                }
            }

            contactsToCheck.add(newContact);
            accountIds.add(newContact.AccountId);
            normalizedEmails.add(normalizeEmail(newContact.Email));
            if (newContact.Id != null) {
                contactIdsToCheck.add(newContact.Id);
            }
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        // Single bulk query. SOQL string matching is case-insensitive, and
        // returned rows are re-checked below using the lower-cased key.
        Set<String> existingDuplicateKeys = new Set<String>();
        for (Contact existingContact : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email IN :normalizedEmails
        ]) {
            // Contacts being checked must never conflict with their own
            // stored record (or with the stored, pre-update values of
            // other contacts being checked in the same save).
            if (
                contactIdsToCheck.contains(existingContact.Id) ||
                existingContact.AccountId == null ||
                String.isBlank(existingContact.Email)
            ) {
                continue;
            }
            existingDuplicateKeys.add(
                duplicateKey(existingContact.AccountId, existingContact.Email)
            );
        }

        Set<String> duplicateKeysSeenInSave = new Set<String>();
        for (Contact contactToCheck : contactsToCheck) {
            String key = duplicateKey(contactToCheck.AccountId, contactToCheck.Email);
            if (existingDuplicateKeys.contains(key) || duplicateKeysSeenInSave.contains(key)) {
                contactToCheck.addError(DUPLICATE_ERROR_MESSAGE);
            } else {
                duplicateKeysSeenInSave.add(key);
            }
        }
    }

    private static String duplicateKey(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + normalizeEmail(email);
    }

    private static String normalizeEmail(String email) {
        return email == null ? null : email.toLowerCase();
    }
}
