/**
 * Maintains Account.FB_Open_Case_Count__c as the number of open
 * (IsClosed = false) Cases for each Account.
 *
 * Runs without sharing so the count reflects all Cases for an Account,
 * not only those visible to the user who created, changed, deleted or
 * undeleted a Case, and so the parent Account can be maintained as part
 * of the Case operation.
 *
 * Each entry point performs at most two SOQL queries and one DML
 * statement, regardless of the number of Cases in the trigger batch.
 */
public without sharing class TA_Case_RollupOpenCount
    implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculateOpenCaseCounts(getAccountIds(triggerNew));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Map<Id, Case> oldCaseById = new Map<Id, Case>();
        if (triggerOld != null) {
            for (SObject record : triggerOld) {
                Case oldCase = (Case) record;
                if (oldCase.Id != null) {
                    oldCaseById.put(oldCase.Id, oldCase);
                }
            }
        }

        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Case newCase = (Case) record;
            Case oldCase = oldCaseById.get(newCase.Id);

            if (oldCase == null) {
                if (newCase.AccountId != null) {
                    accountIds.add(newCase.AccountId);
                }
                continue;
            }

            // Only an Account change or a change in closed status can
            // affect an open-case count.
            if (newCase.AccountId == oldCase.AccountId &&
                newCase.IsClosed == oldCase.IsClosed) {
                continue;
            }

            if (oldCase.AccountId != null) {
                accountIds.add(oldCase.AccountId);
            }
            if (newCase.AccountId != null) {
                accountIds.add(newCase.AccountId);
            }
        }

        recalculateOpenCaseCounts(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculateOpenCaseCounts(getAccountIds(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculateOpenCaseCounts(getAccountIds(triggerNew));
    }

    private static Set<Id> getAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();
        if (records == null) {
            return accountIds;
        }

        for (SObject record : records) {
            Case caseRecord = (Case) record;
            if (caseRecord.AccountId != null) {
                accountIds.add(caseRecord.AccountId);
            }
        }
        return accountIds;
    }

    private void recalculateOpenCaseCounts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCountByAccountId.put(
                (Id) result.get('AccountId'),
                (Integer) result.get('openCount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account accountRecord : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Integer openCount = openCountByAccountId.get(accountRecord.Id);
            Decimal correctCount = Decimal.valueOf(openCount == null ? 0 : openCount);

            if (accountRecord.FB_Open_Case_Count__c != correctCount) {
                accountsToUpdate.add(
                    new Account(
                        Id = accountRecord.Id,
                        FB_Open_Case_Count__c = correctCount
                    )
                );
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
