/**
 * Audit trail for Opportunity Amount changes.
 *
 * Creates one completed Task the first time an Opportunity's Amount is
 * seen to change in a transaction. Static state is transaction-scoped in
 * Apex, so the recursive after-update caused by TA_Opportunity_RoundAmount
 * (Order 20) cannot create a second Task for the same Opportunity.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static final Set<Id> loggedOpportunityIds = new Set<Id>();
    private static final Map<Id, Decimal> amountWhenLastSeenByOpportunityId = new Map<Id, Decimal>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty() || triggerOld == null || triggerOld.isEmpty()) {
            return;
        }

        Map<Id, Opportunity> oldOpportunitiesById = new Map<Id, Opportunity>();
        for (Opportunity oldOpportunity : triggerOld) {
            if (oldOpportunity != null && oldOpportunity.Id != null) {
                oldOpportunitiesById.put(oldOpportunity.Id, oldOpportunity);
            }
        }

        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opportunity : triggerNew) {
            if (
                opportunity == null ||
                opportunity.Id == null ||
                !oldOpportunitiesById.containsKey(opportunity.Id)
            ) {
                continue;
            }

            Opportunity oldOpportunity = oldOpportunitiesById.get(opportunity.Id);
            Decimal previousAmount = oldOpportunity.Amount;
            Decimal newAmount = opportunity.Amount;

            Boolean hasSeenBefore = amountWhenLastSeenByOpportunityId.containsKey(opportunity.Id);
            Decimal amountWhenLastSeen = amountWhenLastSeenByOpportunityId.get(opportunity.Id);
            amountWhenLastSeenByOpportunityId.put(opportunity.Id, newAmount);

            if (newAmount == previousAmount) {
                continue;
            }

            // Already audited in this transaction; any later Amount change
            // for this record in the same transaction is not audited again.
            if (loggedOpportunityIds.contains(opportunity.Id)) {
                continue;
            }

            // A rounding-only recursive update must not become the first
            // audit event when the original update did not change Amount.
            if (
                hasSeenBefore &&
                amountWhenLastSeen != null &&
                previousAmount == amountWhenLastSeen &&
                newAmount == amountWhenLastSeen.setScale(0, System.RoundingMode.HALF_UP)
            ) {
                continue;
            }

            loggedOpportunityIds.add(opportunity.Id);
            tasksToInsert.add(
                new Task(
                    Subject = 'Amount changed',
                    WhatId = opportunity.Id,
                    Status = 'Completed'
                )
            );
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
